import React, { PropsWithChildren, useMemo } from 'react';

import {
  SameValueGroup,
  groupMarkers,
} from '../components/annotations/util/group-markers.js';
import { priorityCompareFn } from '../components/annotations/util/priority-markers.js';
import { HistogramAnnotationsDataContext } from '../contexts/HistogramAnnotationsData.context.js';
import { useHistogramAnnotationsConfig } from '../hooks/useHistogramAnnotationsConfig.js';

const prioritizeMarkers = (groupedMarkers: SameValueGroup[][]) => {
  return [...groupedMarkers].map((overlapMarkers) =>
    [...overlapMarkers].sort(priorityCompareFn),
  );
};

export const HistogramAnnotationsDataProvider = ({
  children,
}: PropsWithChildren) => {
  const { tracks } = useHistogramAnnotationsConfig();
  const derivedData = useMemo(() => {
    return {
      tracks: tracks.map(({ markers, priority: trackPriority, ...rest }) => {
        const { groups, tooltipGroups } = groupMarkers(markers, trackPriority);
        return {
          tooltipMarkers: tooltipGroups,
          prioritizedMarkers: prioritizeMarkers(groups),
          ...rest,
        };
      }),
    };
  }, [tracks]);

  return (
    <HistogramAnnotationsDataContext.Provider value={derivedData}>
      {children}
    </HistogramAnnotationsDataContext.Provider>
  );
};

HistogramAnnotationsDataProvider['displayName'] =
  'HistogramAnnotationsDataProvider';
